definition.script:
def add() {
   def a=2
   def b=3
   def add=a+b
   return add
}

def multiply(first_number, second_number) {
   def multiply=first_number*second_number
   return multiply
}

def subtract(x) {
   def subtract=x-add()
   return subtract
}


pipeline {

    agent {
        label 'nhl2283w_laptop'
    }


    options {
        buildDiscarder(logRotator(
            artifactNumToKeepStr: '', 
            daysToKeepStr: '', 
            numToKeepStr: '6'))
        disableConcurrentBuilds()
        ansiColor('xterm')
        // timeout(time: 30, unit: 'MINUTES')   // timeout on whole pipeline job
    }

    environment {
        ENVIRONMENT_TEST = 25
    }

    parameters {
        choice(
            name: "PARAMETERS_TEST", choices: [66, 0, 2, 3],
            description: 'Number of TEST RERUNS for failed test')
    }



    stages {

        stage("Useing Jenkins Addition[add()] function") {
            steps {
                echo "======= Addition function result is: ${add()}"
            }
        }


        stage("Useing Jenkins Multiplication[multiply()] function") {
            steps {
                echo "******* Multiplication function result is: ${multiply(2,2)}"
            }
        }


        stage("Using Jenkins Subtraction[subtract()] function") {
            steps {
                echo "@@@@@@@ Subtractiontion function result is: ${subtract(14)}"
            }
        }

        stage("Using Jenkins functions with Envinronment and Parameters") {
            steps {
                script{
                    echo "+++++++ Substraction Function with passed Envinronment value of ${env.ENVIRONMENT_TEST} is: ${subtract(env.ENVIRONMENT_TEST.toInteger())}"
                    echo "------- Substraction Function with passed Parameter value of ${params.PARAMETERS_TEST} is: ${subtract(params.PARAMETERS_TEST.toInteger())}"
                }

            }


        }




    }
}
